const { useEffect, useRef, useState } = React;

const LAYERS = {
  modal: { label: "dialog", via: "showModal()", color: "blue" },
  popover: { label: "popover", via: "showPopover()", color: "purple" },
  fullscreen: { label: "全屏元素", via: "requestFullscreen()", color: "orange" },
};

const MethodButton = ({ children, onClick }) => (
  <ui.Button variant="secondary" size="sm" onClick={onClick}>
    <span className="font-tau-mono">{children}</span>
  </ui.Button>
);

const Component = () => {
  const boxRef = useRef(null);
  const dialogRef = useRef(null);
  const popoverRef = useRef(null);
  // top-layer 栈：后进入的在最上面
  const [stack, setStack] = useState([]);
  const [inlineDialog, setInlineDialog] = useState(false);

  const enter = key => setStack(list => [...list.filter(item => item !== key), key]);
  const leave = key => setStack(list => list.filter(item => item !== key));

  useEffect(() => {
    const dialog = dialogRef.current;
    const popover = popoverRef.current;
    const box = boxRef.current;
    const handleClose = () => {
      leave("modal");
      setInlineDialog(false);
    };
    const handleToggle = event => (event.newState === "open" ? enter("popover") : leave("popover"));
    const handleFullscreen = () => (document.fullscreenElement === box ? enter("fullscreen") : leave("fullscreen"));
    dialog.addEventListener("close", handleClose);
    popover.addEventListener("toggle", handleToggle);
    document.addEventListener("fullscreenchange", handleFullscreen);
    return () => {
      dialog.removeEventListener("close", handleClose);
      popover.removeEventListener("toggle", handleToggle);
      document.removeEventListener("fullscreenchange", handleFullscreen);
      // 卸载时把自己放进 top-layer 的元素都撤出来
      if (dialog.open) dialog.close();
      if (popover.matches?.(":popover-open")) popover.hidePopover();
      if (document.fullscreenElement === box) document.exitFullscreen?.();
    };
  }, []);

  const showInline = () => {
    const dialog = dialogRef.current;
    if (dialog.open) dialog.close();
    dialog.show?.();
    setInlineDialog(true);
  };
  const showModal = () => {
    const dialog = dialogRef.current;
    if (dialog.open) dialog.close();
    dialog.showModal?.();
    setInlineDialog(false);
    enter("modal");
  };
  const showPopover = () => popoverRef.current.showPopover?.();
  const toggleFullscreen = () => {
    if (document.fullscreenElement === boxRef.current) document.exitFullscreen?.();
    else boxRef.current.requestFullscreen?.();
  };
  const closeDialog = () => dialogRef.current.close?.();

  return (
    <div className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          dialog::backdrop {
            background: var(--tau-overlay);
            backdrop-filter: blur(4px);
          }
          [popover]::backdrop { background: transparent; }
          .cb-fullscreen:fullscreen {
            display: grid;
            place-items: center;
            background: var(--tau-bg-page);
          }
        }
      `}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(220px,34%)]">
        <div className="relative min-w-0 rounded-tau-md border border-line-1 p-4">
          <div ref={boxRef} className="cb-fullscreen relative z-0 h-[200px] overflow-hidden rounded-tau-md border border-dashed border-line-1 bg-surface">
            <div className="flex flex-col gap-1.5 p-3">
              <span className="text-tau-body text-ink-1">受限容器</span>
              <span className="flex flex-wrap gap-1.5">
                <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-tiny text-ink-2">overflow: hidden</code>
                <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-tiny text-ink-2">z-index: 0</code>
              </span>
              {stack.includes("fullscreen") && (
                <ui.Button variant="secondary" size="sm" icon={icons.Minimize} className="mt-2 self-start" onClick={toggleFullscreen}>
                  退出全屏
                </ui.Button>
              )}
            </div>
            <dialog ref={dialogRef} className="m-auto w-[min(340px,90%)] rounded-tau-md border border-line-1 bg-surface p-0 text-ink-1 shadow-lift">
              <div className="flex flex-col gap-3 p-4">
                <div className="flex items-center gap-2">
                  <span className="text-tau-body text-ink-1">dialog 元素</span>
                  <ui.Tag color={inlineDialog ? "gray" : "blue"}>{inlineDialog ? "普通层级" : "top-layer"}</ui.Tag>
                </div>
                <p className="m-0 text-tau-meta text-ink-2">
                  {inlineDialog
                    ? "show() 打开的对话框留在原处，被容器的 overflow 裁掉，也会被 z-index 更高的遮挡层盖住。"
                    : "showModal() 打开后进入 top-layer，不受祖先 overflow 与 z-index 限制，并带有 ::backdrop。"}
                </p>
                <div className="flex flex-wrap justify-end gap-2">
                  {!inlineDialog && <MethodButton onClick={showPopover}>showPopover()</MethodButton>}
                  <ui.Button variant="primary" size="sm" onClick={closeDialog}>
                    关闭
                  </ui.Button>
                </div>
              </div>
            </dialog>
            <div ref={popoverRef} popover="auto" className="m-auto w-[min(280px,90%)] rounded-tau-md border border-line-1 bg-surface p-4 text-ink-1 shadow-lift">
              <div className="flex flex-col gap-2">
                <span className="text-tau-body text-ink-1">popover 元素</span>
                <p className="m-0 text-tau-meta text-ink-2">它也在受限容器里声明，点击外部或按 Esc 关闭。</p>
              </div>
            </div>
          </div>
          <div className="pointer-events-none absolute inset-x-8 bottom-8 z-10 grid h-[72px] place-items-center rounded-tau-md border border-warn bg-warn-soft">
            <span className="font-tau-mono text-tau-sm text-warn">遮挡层 z-index: 10</span>
          </div>
        </div>
        <div className="flex flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">top-layer 栈（上方为最顶层）</span>
          {stack.length ? (
            <ol className="m-0 flex list-none flex-col-reverse gap-1.5 p-0">
              {stack.map((key, index) => (
                <li key={key} className="flex items-center gap-2 rounded-tau-sm border border-line-1 bg-surface px-2.5 py-1.5">
                  <span className="grid size-5 shrink-0 place-items-center rounded-full bg-hover font-tau-mono text-tau-tiny text-ink-2">{index + 1}</span>
                  <span className="min-w-0 text-tau-sm text-ink-1">{LAYERS[key].label}</span>
                  <ui.Tag color={LAYERS[key].color} className="ml-auto shrink-0">
                    {LAYERS[key].via}
                  </ui.Tag>
                </li>
              ))}
            </ol>
          ) : (
            <p className="m-0 text-tau-meta text-ink-3">{inlineDialog ? "空：show() 不会进入 top-layer" : "空"}</p>
          )}
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <MethodButton onClick={showInline}>dialog.show()</MethodButton>
        <MethodButton onClick={showModal}>dialog.showModal()</MethodButton>
        <MethodButton onClick={showPopover}>showPopover()</MethodButton>
        <MethodButton onClick={toggleFullscreen}>requestFullscreen()</MethodButton>
      </div>
    </div>
  );
};
